	["0F461442"] = {
		Content = "“她是十天前……不，十个月……不，十年……啊……我忘记了。”",
		ContentEN = "\"Ten days ago… no, ten months… or is it ten years… Ah… I can't recall.\"",
		ContentFR = "« Cela fait dix jours... non, dix mois... ou dix ans... Ah... je ne m’en souviens plus... »",
		ContentJP = "「十日前…いや、十か月…いえ、十年…ああ…忘れてしまいました。」",
		ContentKR = "\"10일 전... 아니, 10달... 아니, 10년... 아... 생각이 안 나요.\"",
		ContentTC = "「她是十天前……不，十個月……不，十年……啊……我忘記了。」",
		GUID = "0F461442",
