	["1925DA80"] = {
		Content = "我也没说不相信，今天晚饭吃什么我都想好了，就等着{性别：他|她}回来呢。",
		GUID = "1925DA80",
	},
	["1925DAAA"] = {
		Content = "嗯，别太担心。",
		GUID = "1925DAAA",
	},
	["1925EA6A"] = {
		Content = "总算要离开冰湖城回迪斯玛尼亚了。真冷啊冰湖城，我感觉整个人都冻瘦了一圈，骨头都脆了。",
		GUID = "1925EA6A",
