	["8013423C"] = {
		Content = "当然是要给那些白痴老头听啊！叫的越大声越好！要是能把他们的耳朵震聋，那才最好！",
		GUID = "8013423C",
	},
	["80134266"] = {
		Content = "你和他们有仇吗？",
		GUID = "80134266",
