	["80138238"] = {
		Content = "不可以！",
		GUID = "80138238",
	},
	["80138262"] = {
		Content = "嘿嘿，打小孩咯。",
		GUID = "80138262",
	},
	["8013828C"] = {
		Content = "（母亲因为愤怒而高高扬起的手，却始终悬于半空没有落下来，犹豫再三，她还是将手放了下去。）",
		GUID = "8013828C",
	},
	["801382B6"] = {
		Content = "你这混账孩子！诶！",
		GUID = "801382B6",
	},
	["801382E0"] = {
		Content = "娘……",
		GUID = "801382E0",
	},
	["8013830A"] = {
		Content = "算了算了，去找你那帮狐朋狗友玩吧，记得早点回家。",
