	C8D2974E = {
		Content = "我和刻舟师兄在山外山外面发现了这只小狐狸，它被野兽咬伤了。",
		ContentEN = "Kezhou and I found it just outside the Outer Peaks. It was bitten by something out there.",
		ContentES = "Kezhou y yo lo encontramos a los alrededores de Picos Exteriores. Algo lo mordió allí afuera.",
		ContentFR = "Avec Kezhou, nous l’avons trouvé juste à l’extérieur des Pics Extérieurs. Il a été mordu par une bête sauvage.",
		ContentJP = "カシュウ兄さんと<Default note=\"text:さんがいさん\">山外山</>の外で、この小さなキツネを見つけたの。どうやら獣に噛まれたみたいで……。",
		ContentKR = "각주 사형이랑 산외산 밖에 나갔다가 발견한 꼬마 여우인데, 들짐승한테 물렸나 봐.",
		ContentTC = "我和刻舟師兄在山外山外面發現了這隻小狐狸，它被野獸咬傷了。",
		GUID = "C8D2974E",
	},
	C8D29778 = {
		Content = "刻舟师兄粗枝大叶，完全不知道怎么处理它身上的伤，就只能来找师兄你了。放着不管的话，它很快便会死掉的。",
		ContentEN = "Kezhou's hopeless at this sort of thing, so I came to you. If we leave it, it won't last long.",
		ContentES = "Nuestro hermano Kezhou es un desastre para estas cosas, así que vine a buscarte. Si no lo atendemos pronto, no sobrevivirá.",
